var materials=UnityEngine.Object.FindObjectsByType<UnityEngine.Renderer>(UnityEngine.FindObjectsInactive.Include).SelectMany(r=>r.sharedMaterials).Where(m=>m!=null).Distinct().Where(m=>m.HasProperty("_BaseMap"));
return Newtonsoft.Json.JsonConvert.SerializeObject(materials.Select(m=>new{path=UnityEditor.AssetDatabase.GetAssetPath(m),m.name,shader=m.shader.name,texture=UnityEditor.AssetDatabase.GetAssetPath(m.GetTexture("_BaseMap")),color=m.GetColor("_BaseColor").ToString(),grime=m.HasProperty("_GrimeStrength")?m.GetFloat("_GrimeStrength"):0,metal=m.HasProperty("_Metallic")?m.GetFloat("_Metallic"):0,smooth=m.HasProperty("_Smoothness")?m.GetFloat("_Smoothness"):0}),Newtonsoft.Json.Formatting.Indented);
